# Permission modes as the composer lists them (MODES in web/src/components/Composer.tsx).
MODES = [
    {
        "id": "default",
        "label": "Ask before edits",
        "hint": "Asks before changing files or running commands",
        "icon": "shield-check",
    },
    {
        "id": "acceptEdits",
        "label": "Edit automatically",
