            stl.addWidget(b)
        elif status == "failed":
            b = button(
                "Retry",
                size="sm",
                icon="refresh-cw",
                on_click=lambda: self.reconnect(name_s),
                tooltip=str((st or {}).get("error") or ""),
            )
