        self.worktree: Optional[Json] = session.get("worktree") or None
        self.base = str((self.worktree or {}).get("base") or "HEAD")

        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)

        self._build_toolbar(lay)
        self._build_summary(lay)
