    def _build_summary(self, lay: QVBoxLayout) -> None:
        """Not a repository: the summary line stays put above the scrolling edits (``.changes-summary``)."""
        self.summary_wrap = QWidget()
        sw = QVBoxLayout(self.summary_wrap)
