                win.set_icon_name('pilcrow')
                ico = DIR / 'assets' / 'icon-256.png'
                if ico.exists():
                    win.set_icon_from_file(str(ico))
            except Exception:
                pass
            try:
                st = json.loads(win_state_file.read_text())
                win.set_default_size(int(st.get('w', 1480)), int(st.get('h', 940)))
                if 'x' in st and 'y' in st:
