  if (raw && msgs.some((m) => m.isCompactSummary)) msgs = withEarlierMessages(msgs, raw.byUuid, sessionId);
  for (const m of msgs) {
    m._history = true;
    if (m.type === 'user' && raw?.results.has(m.uuid)) m.tool_use_result = raw.results.get(m.uuid);
