    return true;
  }
  const opener = which('xdg-open') || which('gio') || which('sensible-browser');
  if (!opener) return false;
  const args = opener.endsWith('gio') ? ['open', target] : [target];
  spawn(opener, args, { detached: true, stdio: 'ignore' }).unref();
  return true;
}

