      if (extra.length) r.deps = [...new Set([...(r.deps || []), ...extra])].sort();
    }
    return reposList;
  }

  return { events, list, get, containing, policyFor, defaultsFor, notesFor, resolve, nearest, promptFor, save, remove, register, refresh, scan, annotate };
}

