type Row = { kind: 'hunk'; hunk: DiffHunk; hi: number } | { kind: 'line'; line: DiffLine } | { kind: 'split'; left: DiffLine | null; right: DiffLine | null };

function wordRanges(hunks: DiffHunk[]) {
  const map = new WeakMap<DiffLine, Range[]>();
  for (const h of hunks) {
    const ls = h.lines;
    for (let i = 0; i < ls.length; ) {
      if (ls[i].t !== '-') {
        i++;
        continue;
      }
      const dels: DiffLine[] = [];
      while (i < ls.length && ls[i].t === '-') dels.push(ls[i++]);
      const adds: DiffLine[] = [];
      while (i < ls.length && ls[i].t === '+') adds.push(ls[i++]);
      const n = Math.min(dels.length, adds.length);
      for (let k = 0; k < n; k++) {
        const a = dels[k].s;
        const b = adds[k].s;
        if (a.length > 2000 || b.length > 2000) continue;
        const parts = diffWordsWithSpace(a, b);
        const rd: Range[] = [];
        const ra: Range[] = [];
        let pa = 0;
        let pb = 0;
        let changed = 0;
        for (const p of parts) {
          const len = p.value.length;
          if (p.removed) {
            rd.push([pa, pa + len]);
            pa += len;
            changed += len;
          } else if (p.added) {
            ra.push([pb, pb + len]);
            pb += len;
            changed += len;
          } else {
            pa += len;
            pb += len;
          }
        }
        if (changed < (a.length + b.length) * 0.7) {
          map.set(dels[k], rd);
          map.set(adds[k], ra);
        }
      }
    }
  }
  return map;
}

function useHunkTokens(hunks: DiffHunk[], lang: string) {
  const [state, setState] = useState<Map<DiffLine, Tok[]>>(new Map());
  useEffect(() => {
    let alive = true;
    (async () => {
      const map = new Map<DiffLine, Tok[]>();
      for (const h of hunks) {
        const oldL = h.lines.filter((l) => l.t !== '+');
        const newL = h.lines.filter((l) => l.t !== '-');
        const wanted = () => alive;
        const [ot, nt] = await Promise.all([highlightTokens(oldL.map((l) => l.s).join('\n'), lang, wanted), highlightTokens(newL.map((l) => l.s).join('\n'), lang, wanted)]);
        if (!ot && !nt) return;
        oldL.forEach((l, i) => ot?.[i] && map.set(l, ot[i]));
        newL.forEach((l, i) => nt?.[i] && map.set(l, nt[i]));
      }
      if (alive) setState(map);
    })();
    return () => {
      alive = false;
    };
  }, [hunks, lang]);
  return state;
}

