    if (pid && playbooks.some((p: Playbook) => p.id === pid)) return pid;
    const pb = await call<Playbook>('dispatch.savePlaybook', { fromJob: id }).catch(() => null);
    loadPlaybooks();
    return pb?.id || null;
  };
  const menu = [
    {
      label: 'Run again',
      hint: 'A new job from this brief',
      icon: RotateCw,
      onSelect: async () => {
