        ))}
      </div>
      <div className="dp-runs">
        <table className="dp-table">
          <thead>
            <tr>
              <th>state</th>
              <th>repository</th>
              <th>branch</th>
              <th className="num">elapsed</th>
              <th className="num">Δ files</th>
              <th className="num">cost</th>
              <th>now</th>
            </tr>
          </thead>
          <tbody>
            {runs.map((r) => (
