        <div className="gauge-row">
          <RingGauge pct={pct} tone={tone}>
            {rt?.usage?.afterCompact ? '—' : total ? <Num value={pct * 100} format={(v) => `${Math.round(v)}%`} /> : <Num value={used} format={tokens} />}
          </RingGauge>
          <div className="gauge-side">
