  return (
    <div className={`page${far ? ' far' : ''}${live ? ' live' : ''}`} style={far ? { minHeight: page.est, containIntrinsicSize: `auto ${page.est}px` } : undefined} ref={(el) => observe(el, page.key)}>
      {far ? null : (
        <ErrorBoundary label="This part of the conversation">
