    <div className="menu" ref={ref} role="menu" id={id} aria-label={label} onKeyDown={onKeyDown}>
      {items.map((it, i) => {
        if (it.separator) return <div key={i} className="menu-sep" role="separator" />;
        if (it.heading)
          return (
            <div key={i} className="menu-heading" role="presentation">
              {it.heading}
