const theme: ThemeRegistration = {
  name: 'pilcrow',
  colors: { 'editor.foreground': '#000000', 'editor.background': '#00000000' },
  tokenColors: RULES.map(([scope, dark, , fontStyle], i) => ({ scope, settings: { ...(dark ? { foreground: rowColour(i) } : {}), ...(fontStyle ? { fontStyle } : {}) } })),
