.tnum {
  font-variant-numeric: tabular-nums;
}
.rot {
  transform: rotate(90deg);
}

/* ---- buttons
   Default buttons are quiet fills; one primary (amber) per surface. Every press gives a 2% squeeze. */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-1_5);
  height: 30px;
  padding: 0 var(--sp-3);
  border-radius: var(--r-2);
  background: var(--fill-2);
  color: var(--text);
  font-weight: 500;
  white-space: nowrap;
}
.btn:hover {
  background: var(--fill-3);
}
.btn:disabled {
  opacity: 0.45;
  cursor: default;
}
.btn.primary:disabled {
  opacity: 1;
  background: var(--fill-2);
  color: var(--text-4);
  box-shadow: none;
}
.btn svg {
  opacity: 0.85;
}
.btn.primary {
  background: var(--accent-solid);
  color: var(--accent-ink);
  box-shadow: var(--shadow-solid);
}
.btn.primary:hover {
  background: var(--accent-solid-2);
}
.btn.primary svg {
  opacity: 1;
}
.btn.ghost {
  background: transparent;
  color: var(--text-2);
}
.btn.ghost:hover {
  background: var(--fill-2);
  color: var(--text);
}
.btn.outline {
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--hair-2);
}
.btn.outline:hover {
  background: var(--fill-1);
}
.btn.danger {
  color: var(--err);
}
.btn.danger:hover {
  background: var(--err-wash);
}
.btn.danger.solid {
  background: var(--err-solid);
  color: var(--accent-ink);
}
.btn.danger.solid:hover {
  filter: brightness(1.06);
}
.btn.sm {
  height: 26px;
  padding: 0 var(--sp-2_5);
  font-size: var(--fs-small);
  border-radius: var(--r-2);
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: var(--r-2);
  color: var(--text-3);
  flex: none;
}
.icon-btn:hover {
  background: var(--fill-2);
  color: var(--text);
}
.icon-btn.active,
.icon-btn[aria-expanded='true'] {
  background: var(--fill-2);
  color: var(--text);
}
.icon-btn.sm {
  width: 24px;
  height: 24px;
  border-radius: var(--r-2);
}

.link {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  color: var(--text-2);
  font-size: inherit;
}
.link:hover {
  color: var(--text);
}

/* ---- inputs: filled, no visible border until hover/focus */
.input,
.select,
.textarea {
  width: 100%;
  height: 34px;
  padding: 0 var(--sp-2_75);
  border-radius: var(--r-2);
  border: none;
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
  color: var(--text);
  outline: none;
}
.input::placeholder,
.textarea::placeholder {
  color: var(--text-3);
}
.input:hover,
.textarea:hover {
  box-shadow: inset 0 0 0 1px var(--hair-2);
}
.textarea {
  height: auto;
  padding: var(--sp-2_25) var(--sp-2_75);
  resize: none;
  line-height: 1.55;
}
.input:focus,
.select:focus,
.textarea:focus {
  background: var(--canvas);
  box-shadow: inset 0 0 0 1px var(--hair-3), 0 0 0 3px var(--fill-1);
}
.input.mono {
  font-size: var(--fs-small-plus);
}

.field {
  display: grid;
  gap: var(--sp-1_75);
}
.field > label {
  font-size: var(--fs-small);
  font-weight: 550;
  color: var(--text-2);
}
.hint {
  font-size: var(--fs-small);
  color: var(--text-3);
  line-height: 1.5;
}

/* iOS-style switch */
.switch {
  position: relative;
  width: 34px;
  height: 20px;
  border-radius: var(--r-4);
  background: var(--switch-off);
  flex: none;
}
.switch::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-ink);
  box-shadow: var(--shadow-knob);
}
/* On = lit amber track; the knob stays white in both states so "off" can never read as "on". */
.switch.on {
  background: var(--accent);
}
.switch.on::after {
  transform: translateX(14px);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  height: 19px;
  padding: 0 var(--sp-1_75);
  border-radius: var(--r-pill);
  font-size: var(--fs-micro);
  font-weight: 550;
  color: var(--text-2);
  background: var(--fill-2);
  white-space: nowrap;
}
.badge.accent {
  color: var(--accent-text);
  background: var(--accent-wash);
}
.badge.ok {
  color: var(--ok);
  background: var(--ok-wash);
}
.badge.err {
  color: var(--err);
  background: var(--err-wash);
}
.badge.plan {
  color: var(--plan);
  background: var(--plan-wash);
}
.badge.info {
  color: var(--info);
  background: var(--info-wash);
}

.num-add,
.num-del {
  font-family: var(--font-mono);
  font-size: var(--fs-micro-plus);
  font-variant-numeric: tabular-nums;
}
.num-add {
  color: var(--ok);
}
.num-del {
  color: var(--err);
}
.num-add.zero,
.num-del.zero {
  color: var(--text-3);
}

.empty {
  display: grid;
  place-items: center;
  gap: var(--sp-2);
  padding: var(--sp-11) var(--sp-5);
  text-align: center;
  color: var(--text-3);
  line-height: 1.55;
}

/* Something on its way (ui/Empty Loading): faint lines with a slow sheen where rows will be. */
.loading-rows {
  display: grid;
  gap: var(--sp-5_5);
  padding: var(--sp-4) var(--sp-3_5);
}
.sk-row {
  display: grid;
  gap: var(--sp-2_25);
}
.sk-row .sk {
  height: 11px;
}
.sk {
  height: 14px;
  border-radius: var(--r-pill);
  background: linear-gradient(90deg, var(--fill-1), var(--fill-2), var(--fill-1));
  background-size: 200% 100%;
}
.sk.short {
  width: 60%;
}

/* A part of the page that failed to render (ui/ErrorBoundary.tsx): says so in place, offers a retry. */
.render-fault {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-3);
  border-radius: var(--r-2);
  color: var(--err);
  background: var(--err-wash);
  font-size: var(--fs-small);
}
.render-fault-text {
  flex: 1;
  min-width: 0;
}
.render-fault-why {
  color: var(--text-3);
}
.render-fault-retry {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  color: var(--text-2);
}
