.dp-form > .ns-two,
.dp-form > .dp-inline,
.dp-form > .dp-box {
  margin-top: 0;
}

/* ---- the job card */
.dp-card {
  gap: var(--sp-2);
}
.dp-line {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  min-width: 0;
}
.dp-name {
  font-weight: 600;
  flex: none;
  max-width: 40%;
}
.dp-scope {
  flex: none;
  font-size: var(--fs-small);
}
.dp-counts {
  flex: none;
  font-size: var(--fs-small);
  color: var(--text-2);
}
.dp-cost {
  flex: none;
  font-size: var(--fs-small);
}
.dp-bar {
  display: flex;
  gap: var(--sp-0_5);
  height: 6px;
  flex: 1 1 120px;
  max-width: 220px;
}
.dp-seg {
  flex: 1;
  border-radius: 2px;
  background: var(--fill-2);
}
.dp-seg.done {
  background: var(--ok);
}
.dp-seg.running,
.dp-seg.preparing {
  background: var(--accent);
}
.dp-seg.needs_action {
  background: var(--warn);
}
.dp-seg.failed {
  background: var(--err);
}
.dp-seg.stopped {
  background: var(--text-3);
}

/* ---- a request waiting, the canary waiting: on the board, wells inside the job's card (the control
   room's `.ovc-well`); in the job view, cards of their own (`.ovc.needs`) */
.ovc-well.dp-ask,
.ovc-well.dp-canary {
