.dp-box.dp-plan {
  padding: var(--sp-2_25) var(--sp-3);
}
.dp-inline {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  flex-wrap: wrap;
}
.dp-model {
  max-width: 220px;
}
.dp-targets-top {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
}
.dp-folder {
  max-width: 260px;
}
.dp-targets {
  display: grid;
  gap: var(--sp-0_5);
  padding: var(--sp-1_5);
  border-radius: var(--r-4);
  background: var(--inset);
  box-shadow: inset 0 0 0 0.5px var(--hair);
  max-height: 320px;
  overflow: auto;
}
.dp-target {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-1);
  border-radius: var(--r-2);
}
.dp-target:hover {
  background: var(--fill-1);
}
/* on the hovered row's fill --text-3 falls short of 4.5:1 in the light theme (tokens.css) */
.dp-target:hover .faint {
  color: var(--text);
}
.dp-target-main {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  min-width: 0;
  height: 30px;
  padding: 0 var(--sp-1_5);
  cursor: pointer;
  font-size: var(--fs-ui);
}
.dp-target-main input {
  accent-color: var(--accent);
}
.dp-target-name {
  font-weight: 500;
}
.dp-notes {
  grid-column: 1 / -1;
  margin: 0 var(--sp-1_5) var(--sp-1_5) var(--sp-7_5);
}
.dp-chip {
  font-size: var(--fs-micro);
  font-weight: 600;
  padding: 1px var(--sp-1_75);
  border-radius: 9px;
  background: var(--fill-2);
  color: var(--text-2);
  white-space: nowrap;
}
.dp-chip.ok {
  background: var(--ok-wash);
  color: var(--ok);
}
.dp-chip.warning {
  background: var(--warn-wash);
  color: var(--warn);
}
.dp-chip.blocked {
  background: var(--err-wash);
  color: var(--err);
}
.dp-chip.info {
  background: var(--info-wash);
  color: var(--info);
}
.dp-plan-row {
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr);
  gap: var(--sp-2_5);
  font-size: var(--fs-small);
  color: var(--text-2);
  line-height: 1.45;
}
.dp-plan-tag {
  font-size: var(--fs-micro);
  font-weight: 600;
  color: var(--text-3);
}
.dp-plan-tag.blocked {
  color: var(--err);
}
.dp-plan-tag.warning {
  color: var(--warn);
}

/* ---- the inbox card */
.dp-report .run-foot {
  flex-wrap: wrap;
  row-gap: var(--sp-1_5);
}
.dp-report .run-foot .ellipsis {
  min-width: 0;
  flex: 1 1 160px;
}
.dp-report-rows {
  display: grid;
  gap: var(--sp-0_5);
}
.dp-report-row {
  display: grid;
  grid-template-columns: 12px 150px minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-2_5);
  font-size: var(--fs-small);
}
.dp-report-name {
  font-weight: 500;
}
.dp-report-nums {
  font-size: var(--fs-micro);
}
.dp-prose {
  white-space: pre-wrap;
}
