}
.ovc.needs.decided .ovc-rail {
  background: var(--ok);
}
.ovc-decided {
  color: var(--ok);
}
.ovc-head {
  display: grid;
  gap: var(--sp-0_5);
  min-width: 0;
}
.ovc-title {
  font-weight: 560;
  font-size: var(--fs-ui);
  letter-spacing: -0.004em;
}
.ovc-proj {
  font-size: var(--fs-micro);
  color: var(--text-3);
}
.ovc-row {
  display: flex;
  align-items: flex-start;
  gap: var(--sp-2_5);
}
.ovc-row .ovc-head {
