}
}

.panel-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.panel-body > * {
  flex: 1;
  min-height: 0;
}
.panel-keep {
  flex-direction: column;
  min-height: 0;
}
.panel-keep > * {
  flex: 1;
  min-height: 0;
}

.panel-toolbar {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  min-height: 42px;
  padding: var(--sp-1_5) var(--sp-2_5) var(--sp-1_5) var(--sp-3);
