  padding: var(--sp-1_5) var(--sp-1_5) var(--sp-4_5);
  box-shadow: inset -1px 0 0 var(--hair);
  font-size: var(--fs-small-plus);
}
.tree-row {
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  width: 100%;
  height: 26px;
  padding-right: var(--sp-1_5);
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text-2);
  white-space: nowrap;
}
.tree-row:hover {
  background: var(--fill-1);
  color: var(--text);
}
.tree-row.on {
  background: var(--fill-2);
  color: var(--text);
}
.tree-row svg {
  flex: none;
}
.tree-dir-ico,
.tree-file-ico {
  color: var(--text-3);
}
.tree-row > .lucide-chevron-right {
  color: var(--text-3);
}
.tree-err {
  font-size: var(--fs-micro-plus);
  color: var(--err);
  padding: var(--sp-0_5) var(--sp-1_5);
}
.files-editor {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  background: var(--canvas);
}
.ftabs {
  flex: none;
  display: flex;
  gap: var(--sp-0_5);
  padding: var(--sp-1_5) var(--sp-1_5) 0;
  overflow-x: auto;
  scrollbar-width: none;
  background: var(--chrome);
  box-shadow: inset 0 -1px 0 var(--hair);
}
.ftab {
  display: flex;
  align-items: center;
  flex: none;
  border-radius: var(--r-2) var(--r-2) 0 0;
  font-size: var(--fs-small);
  color: var(--text-3);
}
.ftab:hover {
  color: var(--text);
}
.ftab.on {
  background: var(--canvas);
  color: var(--text);
  box-shadow: 0 0 0 1px var(--hair);
  clip-path: inset(-1px -1px 0 -1px);
}
.ftab-main {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1_5);
  height: 30px;
  padding: 0 var(--sp-1) 0 var(--sp-3);
  font-family: var(--font-mono);
  font-size: var(--fs-small);
}
.ftab-x {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  margin-right: var(--sp-1_25);
  border-radius: var(--r-1);
  color: var(--text-3);
  opacity: 0;
}
.ftab:hover .ftab-x,
.ftab.on .ftab-x {
  opacity: 1;
}
.ftab-x:hover {
  background: var(--fill-2);
  color: var(--text);
}
.dirty-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-2);
}
.editor {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
.editor .cm-editor {
  height: 100%;
}
.editor .cm-editor.cm-focused {
  outline: none;
}
.img-preview {
  flex: 1;
  display: grid;
  place-items: center;
  align-content: center;
  gap: var(--sp-2_5);
  padding: var(--sp-6);
  overflow: auto;
}
.img-preview img {
  max-width: 100%;
  max-height: 70vh;
  border-radius: var(--r-2);
  box-shadow: var(--shadow-card);
  background: repeating-conic-gradient(var(--fill-2) 0 25%, transparent 0 50%) 0 0 / 16px 16px;
}

/* ---------------------------------------------------------------- terminal */

.terms {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.ttab {
  display: inline-flex;
  align-items: center;
  flex: none;
  border-radius: var(--r-2);
  font-size: var(--fs-small);
  color: var(--text-3);
}
.ttab:hover {
  color: var(--text);
}
.ttab button:first-child {
  height: 26px;
  padding: 0 var(--sp-1) 0 var(--sp-2_25);
  font-family: var(--font-mono);
}
.ttab.on {
  background: var(--fill-2);
  color: var(--text);
}
.ttab.exited {
  opacity: 0.55;
}
.ttab-x {
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  margin-right: var(--sp-1);
  border-radius: var(--r-1);
}
.ttab-x:hover {
  background: var(--fill-2);
}
.term-host {
  flex: 1;
  min-height: 0;
  background: var(--chrome);
  padding: var(--sp-2) var(--sp-1) var(--sp-1) var(--sp-3);
}
.xterm-host {
  height: 100%;
}
.xterm-host .xterm-viewport {
  background: transparent !important;
}
.xterm-host .xterm .scrollbar.vertical {
  width: 10px !important;
}
.xterm-host .xterm .scrollbar .slider {
  left: 3px !important;
  width: 5px !important;
  border-radius: var(--r-pill);
  background: var(--fill-3) !important;
}
.xterm-host .xterm .scrollbar .slider:hover,
.xterm-host .xterm .scrollbar .slider.active {
  background: var(--hair-3) !important;
}

/* ---------------------------------------------------------------- preview */

.preview {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.url-bar {
  flex: 1;
  display: flex;
  align-items: center;
  gap: var(--sp-0_5);
  min-width: 0;
}
.url-bar .input {
  height: 28px;
  font-size: var(--fs-small);
}
.preview .chips {
  padding: var(--sp-2) var(--sp-3);
  box-shadow: inset 0 -1px 0 var(--hair);
}
.preview-frame {
  flex: 1;
  min-height: 0;
  width: 100%;
  border: none;
  background: var(--frame);
}

/* ---------------------------------------------------------------- tasks & session info */

.tasks-panel,
.info-panel {
  overflow-y: auto;
  padding: var(--sp-1) var(--sp-4) var(--sp-6);
}
.ps {
  display: grid;
  gap: var(--sp-2_5);
  padding: var(--sp-4) 0 var(--sp-4_5);
  box-shadow: inset 0 -1px 0 var(--hair);
}
.ps:last-child {
  box-shadow: none;
}
.ps-head {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  font-weight: 600;
  font-size: var(--fs-h);
  letter-spacing: -0.01em;
}
.ps-head > svg {
  display: none;
}
.ps-head .faint {
  font-weight: 400;
  margin-left: auto;
  font-size: var(--fs-small);
}
.ps-empty {
  font-size: var(--fs-small);
  color: var(--text-3);
  line-height: 1.5;
}
.progress {
  height: 4px;
  border-radius: var(--r-pill);
  background: var(--fill-2);
  overflow: hidden;
}
.progress > div {
  height: 100%;
  border-radius: var(--r-pill);
  background: var(--text-2);
}
.task-row {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  padding: var(--sp-2_25) var(--sp-2_5) var(--sp-2_25) var(--sp-3);
  border-radius: var(--r-4);
  background: var(--canvas);
  box-shadow: var(--shadow-card);
  font-size: var(--fs-ui);
}
.task-row.done {
  background: transparent;
  box-shadow: none;
  padding: var(--sp-1) var(--sp-0_5);
  color: var(--text-2);
}
.task-sub {
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  font-size: var(--fs-micro-plus);
  margin-top: var(--sp-0_5);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ctx-analyze {
  justify-self: start;
  margin-left: -8px;
  color: var(--text-2);
}
.ctx-bar {
  display: flex;
  gap: var(--sp-0_5);
  height: 6px;
  border-radius: var(--r-pill);
  overflow: hidden;
  background: var(--fill-2);
  margin-bottom: var(--sp-1_5);
}
.ctx-bar > * {
  border-radius: 1px;
}
.ctx-cats {
  display: grid;
  gap: var(--sp-1_25);
}
.ctx-cat {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-small);
  color: var(--text-2);
}
.ctx-swatch {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.kv {
  display: grid;
  grid-template-columns: 112px 1fr;
  gap: var(--sp-2) var(--sp-3);
  font-size: var(--fs-small);
  align-items: baseline;
}
.kv > span:nth-child(odd) {
  color: var(--text-3);
}
.kv > span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.chips.wrap {
  max-height: 200px;
  overflow-y: auto;
}
.mcp-row {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-small);
}
.mcp-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-4);
}
.mcp-dot.connected {
  background: var(--ok);
}
.mcp-dot.failed {
  background: var(--err);
}
.mcp-dot.needs-auth,
.mcp-dot.pending {
  background: var(--accent);
}

.kv-sub {
  margin-left: var(--sp-1);
  font-size: var(--fs-micro-plus);
}

/* ================================================================ timeline (time machine)
   A scrubber on top — one tick per step, taller for messages — and the same steps as a list below,
   joined by a rail. Picking a point opens what that step changed; the footer says how far the
   folder has moved since. */
/* keyboard-operable (the arrows step through the timeline): its focus ring is base.css's */
.history {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.history .panel-toolbar {
  flex: none;
}
.tl-scrub {
  flex: none;
  position: relative;
  padding: var(--sp-7) var(--sp-5) var(--sp-2);
  cursor: ew-resize;
  user-select: none;
  touch-action: none;
  box-shadow: inset 0 -1px 0 var(--hair);
}
.tl-scrub-label {
  position: absolute;
  top: 6px;
  transform: translateX(-50%);
  max-width: 70%;
  padding: 1px var(--sp-1_75);
  border-radius: var(--r-pill);
  background: var(--raised-2);
  font-size: var(--fs-micro);
  color: var(--text-2);
  pointer-events: none;
  white-space: nowrap;
}

.tl-scrub.dragging .tl-cursor {
  transform: scale(1.25);
}

.tl-scrub-track {
  position: relative;
  height: 28px;
}
.tl-scrub-track::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  border-radius: var(--r-pill);
  background: var(--fill-2);
}
.tl-scrub-done {
  position: absolute;
  left: 0;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  border-radius: var(--r-pill);
  background: var(--text-3);
}
.tl-tick {
  position: absolute;
  top: 50%;
  width: 2px;
  height: 8px;
  margin: -4px 0 0 -1px;
  border-radius: var(--r-pill);
  background: var(--hair-3);
}
.tl-tick.changed {
  background: var(--text-4);
}
.tl-tick.past.changed {
  background: var(--text-2);
}
.tl-tick.message,
.tl-tick.start,
.tl-tick.restore,
.tl-tick.external {
  height: 14px;
  margin-top: -7px;
}
.tl-tick.message {
  background: var(--text-3);
}
.tl-tick.external {
  background: var(--warn);
}
.tl-tick.restore {
  background: var(--text-2);
}
.tl-tick.now {
  width: 8px;
  height: 8px;
  margin: -4px 0 0 -4px;
  border-radius: 50%;
  background: var(--raised);
  box-shadow: 0 0 0 2px var(--text-3);
}
.tl-cursor {
  position: absolute;
  top: 50%;
  width: 12px;
  height: 12px;
  margin: -6px 0 0 -6px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--chrome), 0 0 0 4px var(--accent);
  pointer-events: none;
}
.tl-cursor::before {
  content: '';
  position: absolute;
  left: 50%;
  bottom: 100%;
  width: 1px;
  height: 14px;
  margin-bottom: var(--sp-1);
  background: var(--hair-3);
}
.tl-scrub-axis {
  display: flex;
  justify-content: space-between;
  padding: var(--sp-0_5) var(--sp-1) 0;
  font-size: var(--fs-tiny);
  color: var(--text-3);
}

.tl-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: var(--sp-2_5) var(--sp-3) var(--sp-3) var(--sp-2);
}
.tl-row {
  position: relative;
}

.tl-row-btn {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: var(--sp-1_5);
  width: 100%;
  padding: var(--sp-1_25) var(--sp-1_5) var(--sp-1_25) var(--sp-1);
  border-radius: var(--r-2);
  text-align: left;
}
.tl-row-head {
  position: relative;
}
.tl-row-head:hover > .tl-row-btn,
.tl-row.on .tl-row-btn {
  background: var(--fill-1);
}
.tl-row.on .tl-row-btn {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}
.tl-rail {
  position: relative;
  align-self: stretch;
  display: flex;
  justify-content: center;
}
.tl-dot {
  position: relative;
  z-index: 1;
  width: 7px;
  height: 7px;
  margin-top: var(--sp-2_75);
  border-radius: 50%;
  background: var(--card);
  box-shadow: inset 0 0 0 1.5px var(--hair-3);
}
/* the rail's vocabulary: hollow = nothing changed, filled = files changed, a square = you spoke,
   amber = changed outside the conversation, a ring = restored */
.tl-dot.changed {
  background: var(--text-3);
  box-shadow: none;
}
.tl-row.message .tl-dot,
.tl-row.start .tl-dot {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: var(--text-2);
  box-shadow: none;
}
.tl-row.external .tl-dot {
  background: var(--warn);
  box-shadow: none;
}
.tl-row.restore .tl-dot {
  background: var(--card);
  box-shadow: inset 0 0 0 2px var(--text-2);
}
.tl-row.on .tl-dot {
  transform: scale(1.3);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent);
  background: var(--accent);
}
.tl-now-mark {
  margin-top: var(--sp-2);
  color: var(--text-2);
}
.tl-now.on .tl-now-mark {
  color: var(--text);
}
.tl-line {
  position: absolute;
  top: 19px;
  bottom: -11px;
  width: 1px;
  background: var(--hair-2);
}
.tl-main {
  display: grid;
  gap: 1px;
  min-width: 0;
}
.tl-title {
  font-size: var(--fs-small);
  color: var(--text);
}
.tl-row.message .tl-title {
  color: var(--text-2);
  font-style: italic;
}
.tl-row.message .tl-title::before {
  content: '“';
}
.tl-row.message .tl-title::after {
  content: '”';
}
.tl-sub {
  display: flex;
  gap: var(--sp-2);
  font-size: var(--fs-micro);
  color: var(--text-3);
}
/* on the picked or hovered row's fill --text-3 falls short of 4.5:1 (tokens.css) */
.tl-row-head:hover .tl-sub,
.tl-row.on .tl-sub,
.tl-now:hover .tl-sub {
  color: var(--text);
}
.tl-stat {
  display: inline-flex;
  gap: var(--sp-1_25);
  font-size: var(--fs-micro);
  white-space: nowrap;
}
/* The jump to the conversation is a button of its own over the place the row keeps for it. */
.tl-jump-room {
  width: 24px;
  height: 24px;
}
.tl-jump {
  position: absolute;
  top: 50%;
  right: var(--sp-1_5);
  translate: 0 -50%;
  opacity: 0;
}
.tl-row-head:hover .tl-jump,
.tl-row.on .tl-jump,
.tl-jump:focus-visible {
  opacity: 1;
}
.tl-now {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: center;
  width: 100%;
  text-align: left;
  gap: var(--sp-1_5);
  padding: var(--sp-1_25) var(--sp-1_5) var(--sp-1_25) var(--sp-1);
  border-radius: var(--r-2);
  cursor: pointer;
}
.tl-now:hover,
.tl-now.on {
  background: var(--fill-1);
}

.tl-detail {
  margin: 0 0 var(--sp-1_5) var(--sp-5_5);
  padding: var(--sp-2) var(--sp-2) var(--sp-2) var(--sp-2_5);
  border-radius: 0 0 var(--r-2) var(--r-2);
  background: var(--fill-1);
  display: grid;
  gap: var(--sp-1_5);
}
.tl-detail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-2);
}
.tl-note {
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  font-size: var(--fs-small);
}
.tl-file {
  background: var(--raised);
  border-radius: var(--r-2);
}
.tl-file .cfile-head {
  padding-left: var(--sp-1);
}

.tl-since {
  flex: none;
  padding: var(--sp-2) var(--sp-3);
  box-shadow: inset 0 1px 0 var(--hair);
  font-size: var(--fs-small);
}
.tl-since.faint {
  padding: var(--sp-2_5) var(--sp-3_5);
}
.tl-since-btn {
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  width: 100%;
  text-align: left;
  color: var(--text-2);
}
.tl-since-btn .tl-stat {
  margin-left: auto;
}

.tl-since-btn .tool-chev.open {
  transform: rotate(90deg);
}
.tl-since-files {
  display: grid;
  gap: var(--sp-0_5);
  max-height: 180px;
  overflow: auto;
  padding: var(--sp-1_5) 0 0 var(--sp-4_5);
}
.tl-since-file {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-micro);
  color: var(--text-2);
}
.tl-since-file .tl-stat {
  margin-left: auto;
}

/* ================================================================ documents: read, edit, or both */
.doc-area {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}
.doc-area.split {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}
.doc-area.split > :first-child {
  box-shadow: inset -1px 0 0 var(--hair);
}
.doc-area > .editor {
  min-height: 0;
}
.doc-preview {
  min-height: 0;
  overflow: auto;
  padding: var(--sp-5_5) var(--sp-7) var(--sp-14);
}
.doc-md {
  max-width: 720px;
  margin: 0 auto;
  font-size: var(--font-size);
  line-height: 1.7;
}
.doc-md > :first-child {
  margin-top: 0;
}
.doc-area.split .doc-preview {
  padding: var(--sp-4) var(--sp-5) var(--sp-12);
}
.doc-area.split .doc-md {
  font-size: var(--fs-ui-plus);
  line-height: 1.65;
}
.doc-seg {
  margin-right: var(--sp-0_5);
}
.doc-seg button {
  min-width: 28px;
}
.doc-frame-wrap {
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: var(--frame);
}
.doc-frame-bar {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  height: 30px;
  padding: 0 var(--sp-1_5) 0 var(--sp-3);
  font-size: var(--fs-micro);
  background: var(--chrome);
  box-shadow: inset 0 -1px 0 var(--hair);
}
.doc-frame {
  flex: 1;
  min-height: 0;
  width: 100%;
  border: 0;
  background: var(--frame);
}

/* ================================================================ the session gauge (Info) */
.gauge-row {
  display: flex;
  align-items: center;
  gap: var(--sp-4);
}
.gauge-wrap {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
}
.gauge {
  display: block;
}
.gauge-track {
  stroke: var(--fill-2);
}
.gauge-num {
  position: absolute;
  font-size: var(--fs-title);
  font-weight: 600;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}
.gauge-side {
  display: grid;
  gap: var(--sp-2_5);
  min-width: 0;
  flex: 1;
}
.gauge-line {
  font-size: var(--fs-small);
  color: var(--text-3);
}
.gauge-line b {
  font-weight: 600;
  color: var(--text);
}
.stat-row {
  display: flex;
  gap: var(--sp-2);
}
.stat {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: var(--sp-0_5);
  padding: var(--sp-2) var(--sp-2_5) var(--sp-1_75);
  border-radius: var(--r-4);
  background: var(--fill-1);
  box-shadow: inset 0 0 0 0.5px var(--hair);
}
.stat-k {
  font-size: var(--fs-micro);
  color: var(--text-2);
  white-space: nowrap;
}
.stat-v {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
}

